            [46, 'Servicios',         'Medicamentos fuera catálogo',  'farmacia',           '¿PATS cubre medicamentos fuera del catálogo?',                         'No. El manual indica que PATS no incluye medicamentos fuera del catálogo de Farmacia PATS.',                                                                                                                                                              null, 0, null, 'ALTA', 'medicamento fuera catalogo,no esta catalogo,no incluye medicamento',                               'No incluye medicamentos fuera del catálogo Farmacia PATS.',                                                     0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [47, 'Servicios',         'Hospitalización',              'hospitalizacion',    '¿PATS incluye hospitalización?',                                       'La hospitalización no es gratuita. PATS puede otorgar precios preferenciales o descuentos en hospitalización dentro de la red autorizada. El pago se realiza directamente al hospital.',                                                                  null, 0, null, 'ALTA', 'hospitalizacion,internamiento,hospital,precio preferencial,pago hospital',                          'La hospitalización puede tener precio preferencial, pero no es gratuita.',                                      0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [48, 'Servicios',         'Servicios hospitalarios',      'hospitalizacion',    '¿Qué servicios hospitalarios pueden tener precio preferencial?',        'PATS puede ofrecer precio preferencial en servicios hospitalarios dentro de la red autorizada, como hospitalización, procedimientos, estudios, servicios derivados, quirófano o terapia intensiva, según tabulador vigente.',                                    null, 0, null, 'ALTA', 'servicios hospitalarios,hospital,procedimientos,estudios,quirofano,terapia intensiva',              'Los servicios hospitalarios pueden tener precio preferencial según tabulador.',                                  0, 0,  95,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [49, 'Servicios',         'Cirugías',                     'cirugia',            '¿PATS cubre cirugías?',                                                'PATS no cubre cirugías como seguro médico. Puede darte acceso a precios preferenciales en cirugías o procedimientos en quirófano dentro de la red autorizada, siempre que cumplas las reglas de vigencia y uso establecidas.',                                    null, 0, null, 'ALTA', 'cirugia,cubre cirugia,operacion,quirofano,procedimiento quirurgico,no seguro',                       'PATS no cubre como seguro, pero puede dar precios preferenciales en cirugías autorizadas.',                     0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [50, 'Servicios',         'Quirófano',                    'cirugia',            '¿El uso de quirófano tiene descuento con PATS?',                       'El uso de quirófano puede tener precio preferencial dentro de la red autorizada, sujeto al tabulador vigente, condiciones del servicio y reglas aplicables de PATS.',                                                                                      null, 0, null, 'ALTA', 'quirofano,uso quirofano,precio quirofano,descuento quirofano',                                        'Puede aplicar precio preferencial de quirófano según tabulador vigente.',                                       0, 0,  95,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [51, 'Servicios',         'Terapia intensiva',            'terapia_intensiva',  '¿PATS cubre terapia intensiva?',                                       'PATS no cubre terapia intensiva como seguro. Puede otorgar acceso a precios preferenciales en terapia intensiva dentro de la red autorizada, sujeto a consumo y reglas del programa.',                                                                     null, 0, null, 'ALTA', 'terapia intensiva,uci,uti,intensiva,cubre,precio preferencial',                                       'Puede aplicar precio preferencial, pero no cobertura como seguro.',                                             0, 0,  95,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [52, 'Servicios',         'Pago hospital',                'hospitalizacion',    '¿Dónde pago hospitalización, cirugía o servicios hospitalarios?',      'Los servicios hospitalarios, hospitalización, procedimientos de urgencias, cirugías, quirófano o terapia intensiva se pagan directamente al hospital o prestador autorizado correspondiente.',                                                               null, 0, null, 'ALTA', 'pago hospital,donde pago hospitalizacion,cirugia,pagar quirofano,terapia intensiva',                 'Se pagan directamente al hospital o prestador autorizado.',                                                     0, 0,  95,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [53, 'Servicios',         'Regla cirugía vigencia',       'cirugia',            '¿Qué requisitos debo cumplir para usar precios preferenciales en cirugía?', 'Para acceder a precios preferenciales en cirugías o procedimientos de quirófano debes tener PATS activo y vigente. También pueden aplicar reglas especiales de antigüedad, anualidad o pago completo según el caso. Confirma siempre con personal autorizado antes de programar.', null, 0, null, 'ALTA', 'requisitos cirugia,antiguedad,anualidad,pago completo,activo,vigente', 'Debes tener PATS activo y validar reglas especiales antes de cirugía.',                                         1, 1,  90,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [54, 'Precios',           'Costo por servicio',           'precios_servicios',  '¿Cuánto cuesta cada servicio con PATS?',                               'El costo depende del tipo de atención. Consulta general y urgencias pueden ser sin costo dentro de red. Otros servicios como especialistas, laboratorio, imagenología, farmacia, hospitalización, cirugía o terapia intensiva deben revisarse en la lista de precios preferenciales vigente.', null, 0, null, 'ALTA', 'cuanto cuesta servicio,precio servicio,tabulador,lista precios,costo final', 'Depende del servicio; revisa el tabulador vigente PATS.',                                                       0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [55, 'Precios',           'Confirmar costo final',        'precios_servicios',  '¿Debo preguntar el costo antes del servicio?',                         'Sí. Antes de recibir un servicio con precio preferencial, confirma el costo final con el prestador autorizado o personal PATS. Esto evita confusiones por procedimientos, insumos o medicamentos adicionales.',                                                null, 0, null, 'ALTA', 'preguntar costo,costo final,antes del servicio,precio final,confirmar precio',                     'Sí, confirma siempre el costo final antes del servicio.',                                                       0, 0,  95,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [56, 'Precios',           'Precio no coincide',           'precios_servicios',  '¿Qué hago si el precio no coincide con la lista PATS?',                'Si el precio informado no coincide con la lista de precios PATS, solicita revisión con Concierge PATS, admisión o personal autorizado antes de realizar el pago o recibir el servicio.',                                                                   null, 0, null, 'ALTA', 'precio no coincide,me cobran mas,tabulador diferente,lista precios',                               'Solicita revisión con personal autorizado antes de pagar.',                                                     1, 1,  95,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [57, 'Uso',               'Uso ilimitado',                'uso_ilimitado',      '¿Cuántas veces puedo usar PATS?',                                      'El manual indica que PATS tiene uso ilimitado y no considera preexistencias. Sin embargo, ciertos servicios como cirugías, terapia intensiva y algunas atenciones pueden estar sujetos a reglas especiales.',                                                  null, 0, null, 'ALTA', 'cuantas veces,uso ilimitado,limite,usar varias veces,preexistencias',                               'PATS tiene uso ilimitado, pero algunos servicios tienen reglas especiales.',                                    0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [58, 'Uso',               'Preexistencias',               'uso_ilimitado',      '¿PATS tiene preexistencias?',                                          'El manual indica que PATS no tiene preexistencias. Aun así, recuerda que no es un seguro médico; los servicios aplican como beneficios o precios preferenciales dentro de la red autorizada.',                                                            null, 0, null, 'ALTA', 'preexistencias,enfermedad previa,padecimiento previo,no tiene preexistencias',                       'El manual indica que PATS no tiene preexistencias.',                                                            0, 0,  95,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [59, 'Exclusiones',       'No incluido',                  'exclusiones',        '¿Qué no incluye PATS?',                                                'PATS no incluye trasplantes, tratamientos experimentales, tratamientos oncológicos, hemodiálisis, medicamentos fuera del catálogo de Farmacia PATS, atención fuera de la red autorizada, especialistas fuera de la red, estudios fuera de red o cualquier servicio no indicado expresamente dentro del programa.', null, 0, null, 'ALTA', 'no incluye,no cubre,exclusiones,trasplantes,oncológicos,hemodialisis,experimental,fuera red', 'No incluye servicios fuera de red ni tratamientos excluidos como trasplantes, oncológicos o hemodiálisis.',     0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [60, 'Exclusiones',       'Trasplantes',                  'exclusiones',        '¿PATS incluye trasplantes?',                                           'No. El manual indica que PATS no incluye trasplantes.',                                                                                                                                                                                                             null, 0, null, 'ALTA', 'trasplante,trasplantes,transplante,no cubre trasplante',                                             'No. PATS no incluye trasplantes.',                                                                              0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [61, 'Exclusiones',       'Oncología',                    'exclusiones',        '¿PATS incluye tratamientos oncológicos?',                              'No. El manual indica que PATS no incluye tratamientos oncológicos.',                                                                                                                                                                                        null, 0, null, 'ALTA', 'oncologia,cancer,cáncer,tratamiento oncologico,quimioterapia',                                        'No. PATS no incluye tratamientos oncológicos.',                                                                 0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [62, 'Exclusiones',       'Hemodiálisis',                 'exclusiones',        '¿PATS incluye hemodiálisis?',                                          'No. El manual indica que PATS no incluye hemodiálisis.',                                                                                                                                                                                                    null, 0, null, 'ALTA', 'hemodialisis,diálisis,dialisis,riñon,renal',                                                         'No. PATS no incluye hemodiálisis.',                                                                             0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [63, 'Exclusiones',       'Experimental',                 'exclusiones',        '¿PATS incluye tratamientos experimentales?',                           'No. El manual indica que PATS no incluye tratamientos experimentales.',                                                                                                                                                                                     null, 0, null, 'ALTA', 'tratamiento experimental,experimental,ensayo,protocolo experimental',                               'No. PATS no incluye tratamientos experimentales.',                                                              0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [64, 'Exclusiones',       'Fuera de red',                 'fuera_red',          '¿Puedo usar PATS fuera de la red autorizada?',                         'No. Los beneficios y precios preferenciales de PATS aplican dentro de la red autorizada. Atención fuera de red, médicos no afiliados o estudios fuera de red no forman parte de los beneficios.',                                                           null, 0, null, 'ALTA', 'fuera de red,otro hospital,otro medico,no afiliado,no autorizado',                                  'PATS aplica únicamente dentro de la red autorizada.',                                                           0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [65, 'Reglas especiales', 'Mayores de 65 años',           'mayores_65',         '¿Qué pasa si tengo 65 años o más?',                                    'Si al momento de contratar tienes 65 años cumplidos, debes adquirir o incorporar a dos personas adicionales menores de esa edad. De lo contrario, PATS no podrá quedar activo y no podrás acceder a los servicios.',                                            null, 0, null, 'ALTA', '65 años,mayor de 65,adulto mayor,dos personas adicionales,activar',                                  'Si tienes 65 años o más, debes incorporar dos personas adicionales menores de esa edad.',                       0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [66, 'Reglas especiales', 'Menores de edad',              'menores_dependientes','¿Puede usar PATS un menor de edad?',                                   'Sí, pero si el usuario es menor de 18 años, el registro, uso de la app, pago y gestión de servicios estarán asignados a un padre, madre o tutor responsable.',                                                                                           null, 0, null, 'ALTA', 'menor,menores,menor de edad,18 años,tutor,padre,madre',                                              'Sí, pero debe gestionarlo un padre, madre o tutor responsable.',                                                0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [67, 'Reglas especiales', 'Dependientes',                 'menores_dependientes','¿Qué pasa si el usuario es dependiente?',                              'Si el usuario es dependiente, la gestión del registro, app, pagos y servicios debe estar asignada a la persona responsable correspondiente.',                                                                                                             null, 0, null, 'ALTA', 'dependiente,usuario dependiente,tutor,responsable,familiar',                                         'Un usuario dependiente debe ser gestionado por su responsable.',                                                0, 0,  90,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [68, 'Responsabilidad',   'Responsabilidad médica',       'responsabilidad_medica','¿PATS es responsable de la atención médica?',                        'PATS administra el programa de beneficios, pero la atención médica la presta directamente el profesional de salud, hospital, laboratorio, farmacia o prestador correspondiente. La responsabilidad de la calidad, resultado o consecuencias del servicio corresponde al prestador del servicio.', null, 0, null, 'ALTA', 'responsabilidad medica,doctor,hospital,resultado,calidad,negligencia,prestador', 'La atención médica la presta directamente el profesional o institución correspondiente.',                        0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [69, 'Responsabilidad',   'Queja médica',                 'responsabilidad_medica','¿Qué hago si tengo una queja sobre la atención médica?',             'Si tienes una queja sobre la atención médica recibida, debes reportarla al prestador del servicio y también puedes informar a Concierge PATS o personal autorizado para orientación y seguimiento administrativo.',                                          null, 0, null, 'ALTA', 'queja médica,mal servicio,doctor,hospital,reclamo,atencion medica',                                  'Reporta la queja al prestador y avisa a personal autorizado PATS.',                                             1, 1,  85,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [70, 'Cancelación',       'Cancelar PATS',                'cancelacion',        '¿Puedo cancelar PATS?',                                                'La cancelación del contrato PATS puede realizarse mediante aviso por escrito con 30 días de anticipación. La cancelación aplica para el siguiente periodo mensual y no hay reembolso de pagos ya realizados.',                                                  null, 0, null, 'ALTA', 'cancelar,cancelacion,baja,aviso,30 dias,reembolso',                                                   'Sí, con aviso por escrito de 30 días. No hay reembolso de pagos realizados.',                                  0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [71, 'Cancelación',       'No reembolso',                 'cancelacion',        '¿PATS devuelve dinero si cancelo?',                                    'No. El manual indica que no hay reembolso de pagos ya realizados.',                                                                                                                                                                                        null, 0, null, 'ALTA', 'reembolso,devolucion,me regresan dinero,cancelar devolver',                                          'No hay reembolso de pagos ya realizados.',                                                                      0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [72, 'Cancelación',       'Terminación contrato',         'cancelacion',        '¿Cómo puede terminar el contrato PATS?',                               'El contrato puede terminar por falta de pago, acuerdo por escrito entre las partes o incumplimiento de alguna cláusula. En caso de terminación, no hay devolución de dinero.',                                                                             null, 0, null, 'ALTA', 'terminar contrato,contrato,falta de pago,incumplimiento,acuerdo escrito',                            'Puede terminar por falta de pago, acuerdo escrito o incumplimiento.',                                           0, 0,  95,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [73, 'Cancelación',       'Comprar otro PATS',            'cancelacion',        '¿Puedo comprar otro PATS si cancelé o venció el anterior?',            'El manual indica que PATS es personal, exclusivo e intransferible. Si queda vencido, debe revisarse la reactivación bajo las condiciones correspondientes, no tratarse como un pasaporte nuevo para evadir adeudos.',                                          null, 0, null, 'ALTA', 'comprar otro pats,nuevo pasaporte,vencido,reactivar,adeudo',                                          'Si venció, debe revisarse reactivación bajo las condiciones aplicables.',                                        1, 1,  90,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [74, 'Privacidad',        'Datos personales',             'privacidad',         '¿Qué pasa con mis datos personales?',                                  'PATS indica que protege los datos personales mediante medidas como cifrado, firewalls, actualizaciones de seguridad y políticas de privacidad. También permite ejercer derechos ARCO: Acceso, Rectificación, Cancelación y Oposición.',                       null, 0, null, 'ALTA', 'datos personales,privacidad,cifrado,firewall,arco,lfpdppp,proteccion',                                'PATS protege datos personales y permite ejercer derechos ARCO.',                                                0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [75, 'Privacidad',        'Derechos ARCO',                'privacidad',         '¿Qué son los derechos ARCO?',                                          'Los derechos ARCO permiten solicitar Acceso, Rectificación, Cancelación u Oposición respecto al uso de datos personales, conforme a la normativa aplicable en México.',                                                                                   null, 0, null, 'ALTA', 'arco,acceso,rectificacion,cancelacion,oposicion,derechos datos',                                     'ARCO significa Acceso, Rectificación, Cancelación y Oposición.',                                                0, 0,  95,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [76, 'Privacidad',        'Seguridad datos',              'privacidad',         '¿Cómo protege PATS mi información?',                                   'PATS indica medidas de seguridad como cifrado de datos, firewalls, actualizaciones constantes y políticas de privacidad para proteger información almacenada y en tránsito.',                                                                              null, 0, null, 'ALTA', 'cifrado,encriptacion,firewall,seguridad datos,protege informacion',                                  'Usa medidas como cifrado, firewalls y políticas de privacidad.',                                                0, 0,  90,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [77, 'Recomendaciones',   'Uso correcto',                 'recomendaciones',    '¿Qué recomendaciones debo seguir para usar PATS?',                     'Para aprovechar PATS, paga dentro de los primeros 5 días de cada mes, agenda por medios oficiales, verifica que el médico o servicio esté dentro de la red, lleva identificación y QR, pregunta el costo final antes del servicio y mantén actualizados tus datos.', null, 0, null, 'ALTA', 'recomendaciones,consejos,usar bien,pagar a tiempo,medios oficiales,red,qr,costo final', 'Paga a tiempo, agenda por medios oficiales, verifica red y lleva identificación y QR.',                         0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [78, 'Recomendaciones',   'Verificar red',                'recomendaciones',    '¿Por qué debo verificar la red antes de atenderme?',                   'Debes verificar la red porque los beneficios y precios preferenciales aplican únicamente con prestadores autorizados PATS. Si acudes fuera de red, los beneficios pueden no aplicar.',                                                                      null, 0, null, 'ALTA', 'verificar red,red autorizada,medico afiliado,prestador autorizado,fuera de red',                    'Porque los beneficios aplican únicamente dentro de red autorizada.',                                            0, 0, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [79, 'Recomendaciones',   'Actualizar datos',             'recomendaciones',    '¿Debo actualizar mis datos en la app?',                                 'Sí. Si cambias domicilio, correo, teléfono u otros datos, debes actualizarlos en tu perfil de la app oficial o solicitar apoyo a personal autorizado.',                                                                                                      null, 0, null, 'ALTA', 'actualizar datos,cambiar domicilio,cambiar telefono,cambiar correo,perfil',                          'Sí, mantén tus datos actualizados.',                                                                            1, 1,  90,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [80, 'Canalización',      'Duda no resuelta',             'canalizar',          '¿Qué hago si mi duda no aparece en el manual?',                        'Si la duda no aparece claramente en el manual o requiere revisar tu estatus, pago, red, tabulador o caso particular, debe canalizarse con Concierge PATS, admisión o personal autorizado.',                                                                   null, 0, null, 'ALTA', 'duda,no aparece,no se,caso especial,concierge,admision,soporte',                                     'Canaliza la duda con Concierge PATS o personal autorizado.',                                                    1, 1,  95,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [81, 'Canalización',      'Validación por admisión',      'canalizar',          '¿Qué debe validar admisión antes de aplicar beneficios PATS?',         'Admisión o concierge debe validar que el usuario esté activo, que presente identificación y QR, que el prestador esté dentro de la red autorizada y que el servicio corresponda al tabulador o beneficio vigente.',                                            null, 0, null, 'ALTA', 'admision,validar,activo,qr,identificacion,red,tabulador,concierge',                                  'Validar activo, identificación, QR, red autorizada y tabulador aplicable.',                                     1, 1, 100,  1, 'MANUAL_USUARIO_PATS_COMPLETO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 07:46:27', '2026-04-24 07:46:27'],
            [82, 'Vigencia',          'Pasaporte vencido',            'falta_pago',         '¿Qué hacer si el usuario llega con PATS vencido?',                     'Si el usuario llega con su PATS o pasaporte vencido, se debe validar su estatus antes de aplicar cualquier beneficio. Si aparece vencido o inactivo, se le debe explicar que para usar los beneficios necesita reactivarlo conforme a las reglas vigentes. La reactivación puede requerir cubrir mensualidades vencidas, mensualidad vigente y la cuota de reactivación aplicable. No se deben confirmar beneficios, precios especiales o servicios como activos hasta validar el estatus.', null, 0, null, 'ALTA', 'pasaporte vencido,pats vencido,paciente con pasaporte vencido,usuario con pats vencido,vence,vencido,inactivo,no vigente,reactivar,reactivacion,falta de pago,estatus,pats vigencias', 'Si el PATS está vencido, primero valida estatus. Si está inactivo, debe reactivarse antes de aplicar beneficios.', 1, 1, 980, 1, 'APRENDIZAJE_SUPERVISADO', 'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 14:47:49', '2026-04-24 14:47:49'],
            [83, 'Identidad PATS',    'Definición',                   'que_es_pats',        'que es PATS',                                                          'PATS, Pasaporte a tu Salud, es un programa de beneficios, descuentos y precios preferenciales en servicios médicos privados dentro de la red autorizada. Es personal, exclusivo e intransferible. Importante: PATS no es un seguro médico.',                   null, 0, null, 'ALTA', 'pats,que es pats,q es pats,pasaporte a tu salud,programa beneficios,beneficios medicos,descuentos,precio preferencial,no es seguro,red autorizada', 'PATS es un programa de beneficios y descuentos médicos. No es un seguro médico.',                               0, 0,1000,  1, 'ENTRENAMIENTO_BASE',          'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 15:54:25', '2026-04-24 15:54:25'],
            [84, 'Identidad PATS',    'No seguro',                    'no_seguro',          'PATS es un seguro medico',                                             'No. PATS no es un seguro médico, no es póliza y no debe explicarse como cobertura médica. Es un programa de beneficios, descuentos y precios preferenciales dentro de la red autorizada y bajo reglas vigentes.',                                           null, 0, null, 'ALTA', 'seguro medico,poliza,cobertura,pats cubre,que cubre,no seguro,no es seguro,beneficios,descuentos', 'PATS no es seguro médico. Es un programa de beneficios y precios preferenciales.',                              0, 0, 990,  1, 'ENTRENAMIENTO_BASE',          'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 15:54:25', '2026-04-24 15:54:25'],
            [85, 'Pagos',             'Lugar de pago',                'pago',               'donde se paga PATS',                                                   'Para pagar PATS se debe usar el medio autorizado por la unidad o por el programa. Si el usuario está en la unidad, puede ser canalizado a Admisión o Caja según el flujo interno. No confirmes un pago como aplicado hasta validar el comprobante o el registro correspondiente.', null, 0, null, 'ALTA', 'donde se paga,donde pago,como pago,pagar en caja,caja,admision,medios de pago,formas de pago,mis pagos', 'El pago debe realizarse por medios autorizados. Si está en unidad, canaliza a Admisión o Caja según corresponda.', 0, 0, 970,  1, 'ENTRENAMIENTO_BASE',          'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 15:54:25', '2026-04-24 15:54:25'],
            [86, 'Pagos',             'Medios de pago',               'pago',               'medios de pago PATS',                                                  'Los medios de pago pueden depender de la unidad, del flujo operativo y del tipo de pago. Para orientar al usuario, indica que se validará el medio autorizado disponible. Si presenta comprobante, se debe revisar referencia, monto, fecha y concepto antes de confirmar.', null, 0, null, 'ALTA', 'medios de pago,formas de pago,opciones de pago,pago en caja,transferencia,comprobante,referencia,recibo,voucher', 'Los medios de pago deben validarse según la unidad y el flujo autorizado.',                                     0, 0, 965,  1, 'ENTRENAMIENTO_BASE',          'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 15:54:25', '2026-04-24 15:54:25'],
            [87, 'Pagos',             'Costo mensual',                'costo',              'cuanto cuesta PATS al mes',                                            'El pago mensual de PATS es de $800 MXN. Antes de confirmar cobros adicionales, adeudos o reactivaciones, se debe validar el estatus del usuario y el periodo aplicable.',                                                                                  null, 0, null, 'ALTA', 'cuanto cuesta,costo mensual,pago mensual,mensualidad,precio pats,cuanto vale,800,pats al mes',      'El pago mensual de PATS es de $800 MXN.',                                                                       0, 0, 960,  1, 'ENTRENAMIENTO_BASE',          'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 15:54:25', '2026-04-24 15:54:25'],
            [88, 'Pagos',             'Costo anual',                  'costo',              'cuanto cuesta PATS anual',                                             'El pago anual de PATS es de $9,600 MXN. Antes de confirmar renovación, adeudos o reactivación, se debe validar el estatus vigente del usuario.',                                                                                                            null, 0, null, 'ALTA', 'costo anual,pago anual,anualidad,precio anual,9600,cuanto cuesta anual,pats anual',               'El pago anual de PATS es de $9,600 MXN.',                                                                       0, 0, 960,  1, 'ENTRENAMIENTO_BASE',          'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 15:54:25', '2026-04-24 15:54:25'],
            [89, 'Vigencia',          'Consulta de estatus',          'vigencia',           'como saber si PATS esta activo',                                       'Para saber si PATS está activo o vigente se debe validar el estatus en la fuente autorizada. No se deben aplicar beneficios ni confirmar vigencia solo por lo que indique el usuario; debe revisarse el registro correspondiente.',                            null, 0, null, 'ALTA', 'vigencia,activo,esta activo,esta vigente,donde veo vigencia,pats vigencias,estatus,validar estatus', 'La vigencia debe validarse en la fuente autorizada antes de aplicar beneficios.',                               1, 1, 955,  1, 'ENTRENAMIENTO_BASE',          'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 15:54:25', '2026-04-24 15:54:25'],
            [90, 'Vigencia',          'Pasaporte vencido',            'falta_pago',         'paciente llega con pasaporte vencido',                                 'Si el usuario llega con PATS o pasaporte vencido, primero se debe validar su estatus. Si aparece vencido o inactivo, debe explicarse que necesita reactivarlo antes de aplicar beneficios. No se deben confirmar beneficios, precios especiales o servicios como activos hasta validar la vigencia.', null, 0, null, 'ALTA', 'pasaporte vencido,pats vencido,pasaporte venido,no vigente,inactivo,se vencio,reactivar,falta de pago,adeudo,pats vigencias', 'Si PATS está vencido, primero valida estatus. Si está inactivo, debe reactivarse antes de aplicar beneficios.', 1, 1, 980,  1, 'ENTRENAMIENTO_BASE',          'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 15:54:25', '2026-04-24 15:54:25'],
            [91, 'Reactivación',      'Reactivar PATS',               'reactivacion',       'como se reactiva PATS',                                                'La reactivación de PATS requiere validar el estatus, adeudos o periodos pendientes y el comprobante de pago si existe. No se debe cambiar el estatus ni prometer reactivación inmediata sin evidencia válida y validación autorizada.',                       null, 0, null, 'ALTA', 'reactivar,reactivacion,activar pasaporte,volver a usar,pats vencido,comprobante,voucher,pago,adeudo', 'Para reactivar PATS, primero valida estatus, adeudo y comprobante antes de confirmar.',                         1, 1, 965,  1, 'ENTRENAMIENTO_BASE',          'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 15:54:25', '2026-04-24 15:54:25'],
            [92, 'Soporte',           'Quién ayuda',                  'soporte',            'quien ayuda con PATS',                                                 'Si el usuario necesita ayuda con PATS, debe ser orientado por Concierge, Admisión, Caja o ADMINPATS según el caso. Si se trata de vigencia, pago, reactivación, cobro, precio o inconsistencia, debe canalizarse al responsable autorizado.',                  null, 0, null, 'ALTA', 'quien ayuda,quien me ayuda,a quien lo mando,soporte pats,concierge,admision,caja,adminpats,quien resuelve', 'Concierge, Admisión, Caja o ADMINPATS pueden orientar según el tipo de caso.',                                  0, 0, 950,  1, 'ENTRENAMIENTO_BASE',          'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 15:54:25', '2026-04-24 15:54:25'],
            [93, 'Cotización',        'Quién cotiza',                 'cotizacion',         'quien cotiza en PATS',                                                 'Las cotizaciones de servicios, procedimientos o cirugías deben realizarse por el área o módulo autorizado. El personal no debe dar precios de memoria. Si es cirugía o procedimiento, debe validarse en el flujo correspondiente, como LEAD+ o el módulo autorizado.', null, 0, null, 'ALTA', 'quien cotiza,cotizar,cotizacion,presupuesto,precio cirugia,procedimiento,lead,lead+,quien hace cotizacion', 'Las cotizaciones deben hacerse por el área o módulo autorizado; no se deben dar precios de memoria.',           0, 0, 950,  1, 'ENTRENAMIENTO_BASE',          'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 15:54:25', '2026-04-24 15:54:25'],
            [94, 'Precios',           'Precio de servicio',           'precios_servicios',  'quiero precio de un servicio PATS',                                    'Para consultar el precio de un servicio PATS se debe validar en el tabulador o módulo autorizado. No se deben confirmar precios de memoria, especialmente si depende de unidad, vigencia, red, estudio, procedimiento o promoción.',                            null, 0, null, 'ALTA', 'quiero precio,precio servicio,precio estudio,cuanto cuesta servicio,pats money,money,tabulador,precio preferencial', 'Los precios deben validarse en el tabulador o módulo autorizado antes de confirmarse.',                         0, 0, 940,  1, 'ENTRENAMIENTO_BASE',          'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 15:54:25', '2026-04-24 15:54:25'],
            [95, 'Beneficios',        'Qué incluye',                  'beneficios',         'que incluye PATS',                                                     'PATS puede incluir beneficios, descuentos y precios preferenciales en servicios médicos privados dentro de la red autorizada. La aplicación específica depende del servicio, vigencia, unidad y reglas vigentes. No todos los servicios son gratuitos.',         null, 0, null, 'ALTA', 'que incluye,beneficios,servicios incluidos,consulta,urgencias,laboratorio,imagenologia,farmacia,precio preferencial,no todo gratis', 'PATS incluye beneficios y precios preferenciales, pero no todos los servicios son gratuitos.',                  0, 0, 940,  1, 'ENTRENAMIENTO_BASE',          'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 15:54:25', '2026-04-24 15:54:25'],
            [96, 'Beneficios',        'No todo es gratis',            'beneficios',         'todos los servicios son gratis con PATS',                               'No. No todos los servicios son gratis con PATS. Algunos servicios pueden tener beneficio, descuento o precio preferencial, pero se debe validar cada caso según la red, vigencia, tabulador y reglas actuales.',                                              null, 0, null, 'ALTA', 'todo gratis,gratis,todos los servicios gratis,no todo gratis,beneficios,descuento,precio preferencial', 'No todos los servicios son gratis; se debe validar cada servicio.',                                             0, 0, 935,  1, 'ENTRENAMIENTO_BASE',          'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 15:54:25', '2026-04-24 15:54:25'],
            [97, 'Quejas',            'Cobro incorrecto',             'queja_cobro',        'le cobraron mal con PATS',                                             'Si el usuario reporta que le cobraron mal o no respetaron un beneficio, se debe escuchar, registrar la situación y validar el caso con la fuente correspondiente. No se debe prometer devolución, ajuste o corrección sin revisión autorizada.',               null, 0, null, 'ALTA', 'cobraron mal,cobro incorrecto,no respetaron precio,no respetaron descuento,queja,reclamo,inconformidad,cobraron de mas', 'Si reporta cobro incorrecto, registra y valida antes de prometer ajustes.',                                     1, 1, 930,  1, 'ENTRENAMIENTO_BASE',          'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 15:54:25', '2026-04-24 15:54:25'],
            [98, 'Aprendizaje supervisado','Respuesta express',        'aprendizaje_supervisado','oxxo',                                                            'En OXXO puedes realizar el pago del pasaporte',                                                                                                                                                                                                                     null, 0, null, 'ALTA', 'oxxo,aprendizaje_supervisado',                                                                       'En OXXO puedes realizar el pago del pasaporte',                                                                 0, 0, 900,  1, 'APRENDIZAJE_SUPERVISADO',     'PATS_MANUAL_2026', 'GENERAL', '2026-04-24 19:35:42', '2026-04-24 19:35:42'],
        ];

        $cols = ['id', 'categoria', 'subcategoria', 'intent', 'pregunta_base', 'respuesta', 'nota_operativa', 'requiere_revision', 'observacion_revision', 'nivel_confianza', 'keywords', 'respuesta_corta', 'requiere_login', 'requiere_datos_usuario', 'prioridad', 'activo', 'fuente', 'version_conocimiento', 'canal', 'created_at', 'updated_at'];

        $inserts = array_map(fn ($r) => array_combine($cols, $r), $rows);

        foreach (array_chunk($inserts, 20) as $chunk) {
            DB::table('pats_bot_knowledge')->insert($chunk);
        }
    }
